import json
with open('$FILE', 'rb') as f:
    raw = f.read()
outer = json.loads(raw)
inner = json.loads(outer['result'])
exps = inner['data']['experiments']

# remaining top-10 DONE (ranks 11-20 and all negative ones worth knowing)
done_exps = [(eid, e) for eid, e in exps.items() if e['status'] == 'DONE']
done_exps.sort(key=lambda x: x[1].get('completed_at',''), reverse=True)

print('=== RANKS 11-15 MOST RECENT DONE ===')
for eid, e in done_exps[10:15]:
    print(f'{eid}: status={e[\"status\"]}, conclusion={e.get(\"conclusion\")}, completed_at={e.get(\"completed_at\")}, hypothesis={e.get(\"spec\",{}).get(\"hypothesis\")}')
    m = e.get('metrics') or {}
    if m:
        for k in ['prove_rate','mean_isr','eval_prove_rate','eval_mean_isr']:
            if k in m: print(f'  {k}={m[k]}')
    print()

print()
print('=== ALL NEGATIVE EXPERIMENTS ===')
for eid, e in exps.items():
    if e.get('conclusion') == 'negative':
        m = e.get('metrics') or {}
        print(f'{eid}: completed={e.get(\"completed_at\")}')
        print(f'  hyp: {e.get(\"spec\",{}).get(\"hypothesis\")}')
        print(f'  notes: {e.get(\"notes\",\"\")[:200]}')
        if m:
            for k in ['prove_rate','mean_isr','eval_prove_rate','eval_mean_isr']:
                if k in m: print(f'  {k}={m[k]}')
        print()
